// PHASE 2 STEP 1: observe, do not interpret.
// The brief is explicit -- log the raw Vapi payload and inspect it before
// building anything downstream. Nothing here assumes a schema; it surfaces a
// shallow map of what actually arrived so the real shape can be read off an
// execution, then keeps the untouched payload alongside it.
const raw = $input.first().json;
const body = raw.body !== undefined ? raw.body : raw;
const msg  = (body && body.message !== undefined) ? body.message : body;

const typeOf = (v) => Array.isArray(v) ? 'array[' + v.length + ']' : (v === null ? 'null' : typeof v);

const shape = {};
if (msg && typeof msg === 'object') {
  for (const k of Object.keys(msg)) {
    const v = msg[k];
    shape[k] = typeOf(v);
    if (v && typeof v === 'object' && !Array.isArray(v)) {
      shape[k] += ' {' + Object.keys(v).slice(0, 25).join(',') + '}';
    }
  }
}

// Probe the fields Workflow B will eventually need, without depending on them.
const probe = {
  serverMessageType: msg && msg.type,
  endedReason:       msg && msg.endedReason,
  hasTranscript:     !!(msg && msg.transcript),
  transcriptChars:   msg && msg.transcript ? String(msg.transcript).length : 0,
  hasMessagesArray:  !!(msg && Array.isArray(msg.messages)),
  hasArtifact:       !!(msg && msg.artifact),
  hasRecordingUrl:   !!(msg && (msg.recordingUrl || (msg.artifact && msg.artifact.recordingUrl))),
  hasSummary:        !!(msg && (msg.summary || (msg.analysis && msg.analysis.summary))),
  durationSeconds:   msg && (msg.durationSeconds || msg.durationMs),
  callId:            msg && msg.call && msg.call.id,
  assistantId:       (msg && msg.assistant && msg.assistant.id) || (msg && msg.call && msg.call.assistantId) || null,
  // The whole P1 question: does metadata survive the call boundary?
  metadataFromAssistant: msg && msg.assistant && msg.assistant.metadata ? msg.assistant.metadata : null,
  metadataFromCall:      msg && msg.call && msg.call.metadata ? msg.call.metadata : null,
  metadataTopLevel:      msg && msg.metadata ? msg.metadata : null
};

probe.metadataFound = !!(probe.metadataFromAssistant || probe.metadataFromCall || probe.metadataTopLevel);
const md = probe.metadataFromAssistant || probe.metadataFromCall || probe.metadataTopLevel || {};
probe.sessionId    = md.sessionId    || null;
probe.coachEmail   = md.coachEmail   || null;
probe.participantName = md.participantName || null;

return [{ json: { receivedAt: new Date().toISOString(), probe, shape, raw } }];

// SAFETY: this project owns only assistants named `INT ...` and phone numbers
// named `INTERVIEW-nn`. The same Vapi account may also run production phone
// lines and alerting systems. Every filter below is a hard gate, not a heuristic.
// See PLAYBOOK.md section 7 (pool ownership rule).
const ASSISTANT_OWNED = (name) => /^INT /.test(String(name || ''));
const NUMBER_OWNED    = (name) => /^INTERVIEW-\d+$/.test(String(name || ''));

// Decide what to release now that the call is over. Runs even if metadata did
// not survive, because the assistantId alone is enough to tear down.
const p = $input.first().json.probe || {};
const assistantId = p.assistantId || null;

return [{ json: {
  assistantId,
  sessionId: p.sessionId,
  reason: 'end-of-call',
  releasable: !!assistantId
}}];

// SAFETY: this project owns only assistants named `INT ...` and phone numbers
// named `INTERVIEW-nn`. The same Vapi account may also run production phone
// lines and alerting systems. Every filter below is a hard gate, not a heuristic.
// See PLAYBOOK.md section 7 (pool ownership rule).
const ASSISTANT_OWNED = (name) => /^INT /.test(String(name || ''));
const NUMBER_OWNED    = (name) => /^INTERVIEW-\d+$/.test(String(name || ''));

// Which pool number is currently bound to the assistant that just finished?
const target = $('Extract Release Target').first().json;

const items = $input.all();
let nums = (items.length === 1 && Array.isArray(items[0].json))
  ? items[0].json
  : items.map(i => i.json).filter(n => n && (n.id || n.number));

// Only ever consider this project's own numbers.
const pool = nums.filter(n => NUMBER_OWNED(n.name));
const bound = pool.find(n => n.assistantId && n.assistantId === target.assistantId);

return [{ json: {
  assistantId: target.assistantId,
  sessionId: target.sessionId,
  phoneNumberId: bound ? bound.id : null,
  phoneNumberName: bound ? bound.name : null,
  hasNumber: !!bound
}}];

// SAFETY: this project owns only assistants named `INT ...` and phone numbers
// named `INTERVIEW-nn`. The same Vapi account may also run production phone
// lines and alerting systems. Every filter below is a hard gate, not a heuristic.
// See PLAYBOOK.md section 7 (pool ownership rule).
const ASSISTANT_OWNED = (name) => /^INT /.test(String(name || ''));
const NUMBER_OWNED    = (name) => /^INTERVIEW-\d+$/.test(String(name || ''));

// Snapshot the pool so the sweep can match numbers to stale assistants.
const items = $input.all();
let nums = (items.length === 1 && Array.isArray(items[0].json))
  ? items[0].json
  : items.map(i => i.json).filter(n => n && (n.id || n.number));

const pool = nums.filter(n => NUMBER_OWNED(n.name));

return [{ json: {
  bindings: pool.map(n => ({ id: n.id, name: n.name, assistantId: n.assistantId || null })),
  poolSize: pool.length,
  boundCount: pool.filter(n => !!n.assistantId).length,
  freeCount: pool.filter(n => !n.assistantId).length
}}];

// SAFETY: this project owns only assistants named `INT ...` and phone numbers
// named `INTERVIEW-nn`. The same Vapi account may also run production phone
// lines and alerting systems. Every filter below is a hard gate, not a heuristic.
// See PLAYBOOK.md section 7 (pool ownership rule).
const ASSISTANT_OWNED = (name) => /^INT /.test(String(name || ''));
const NUMBER_OWNED    = (name) => /^INTERVIEW-\d+$/.test(String(name || ''));

// Sweep sessions that were provisioned but never cleaned up.
//
// Chain 1 releases a session the moment its call ends. This catches the case the
// brief calls out: a session provisioned for someone who never dialled. Without
// it the pool drains permanently and silently (P3).
const STALE_AFTER_MINUTES = 120;   // an interview is capped at 25 min, so 2h is generous

const bindings = $('Collect Pool Bindings').first().json.bindings || [];
const byAssistant = {};
for (const b of bindings) {
  if (b.assistantId) byAssistant[b.assistantId] = b;
}

const items = $input.all();
let assistants = (items.length === 1 && Array.isArray(items[0].json))
  ? items[0].json
  : items.map(i => i.json).filter(a => a && a.id);

const now = Date.now();
const out = [];

for (const a of assistants) {
  if (!ASSISTANT_OWNED(a.name)) continue;              // hard gate
  const ageMin = (now - new Date(a.createdAt).getTime()) / 60000;
  if (ageMin < STALE_AFTER_MINUTES) continue;
  const b = byAssistant[a.id];
  out.push({ json: {
    assistantId: a.id,
    assistantName: a.name,
    ageMinutes: Math.round(ageMin),
    phoneNumberId: b ? b.id : null,
    phoneNumberName: b ? b.name : null,
    hasNumber: !!b,
    reason: 'stale-sweep'
  }});
}

// Also unbind pool numbers pointing at an assistant that no longer exists.
const liveIds = new Set(assistants.map(a => a.id));
for (const b of bindings) {
  if (b.assistantId && !liveIds.has(b.assistantId)) {
    out.push({ json: {
      assistantId: null,
      assistantName: '(already deleted)',
      ageMinutes: null,
      phoneNumberId: b.id,
      phoneNumberName: b.name,
      hasNumber: true,
      reason: 'orphaned-binding'
    }});
  }
}

return out;

// Rebuild the deletion list after the unbind.
// $json here is the Vapi phone-number object returned by PATCH, so the original
// stale-session fields are gone. Map back by phone number id -- deterministic,
// with no reliance on pairedItem surviving an HTTP node.
const stale = $('Find Stale Sessions').all().map(i => i.json);
const out = [];

for (const item of $input.all()) {
  const numberId = item.json && item.json.id;
  const match = stale.find(s => s.phoneNumberId === numberId);
  if (!match) continue;
  if (!match.assistantId) continue;   // orphaned binding: number freed, assistant already gone
  out.push({ json: match });
}

return out;

// Emit one SQL statement that syncs the allocator to what Vapi actually holds.
// Vapi is authoritative for bindings; this table is authoritative for allocation.
// After a sweep the two can disagree, so free every row whose number is unbound.
//
// Runs on every schedule tick as its own branch -- NOT downstream of the teardown --
// because when nothing is stale the teardown chain emits no items and anything
// hanging off it never executes.
const items = $input.all();
let nums = (items.length === 1 && Array.isArray(items[0].json))
  ? items[0].json
  : items.map(i => i.json).filter(n => n && (n.id || n.number));

const pool = nums.filter(n => /^INTERVIEW-\d+$/.test(String(n.name || '')));
const free = pool.filter(n => !n.assistantId).map(n => n.id);

const esc = (s) => "'" + String(s).replace(/'/g, "''") + "'";

if (free.length === 0) {
  return [{ json: { sql: 'SELECT 0 AS released;', freeCount: 0, poolSize: pool.length } }];
}

const inList = free.map(esc).join(', ');

// `target` captures session_id BEFORE it is nulled. Postgres RETURNING yields the
// NEW row, so RETURNING session_id after SET session_id = NULL returns NULL and the
// join to interview_sessions silently matches nothing -- rows got freed but their
// sessions were never marked swept.
const sql = [
  'WITH target AS (',
  '  SELECT phone_number_id, session_id',
  '  FROM interview_number_pool',
  '  WHERE phone_number_id IN (' + inList + ')',
  '    AND session_id IS NOT NULL',
  '),',
  'freed AS (',
  '  UPDATE interview_number_pool p',
  '  SET session_id = NULL, assistant_id = NULL, released_at = NOW(), updated_at = NOW()',
  '  FROM target t',
  '  WHERE p.phone_number_id = t.phone_number_id',
  '  RETURNING t.session_id AS sid',
  ')',
  'UPDATE interview_sessions s',
  "SET status = CASE WHEN s.status IN ('provisioning','ready','provisioned') THEN 'swept' ELSE s.status END,",
  '    released_at = COALESCE(s.released_at, NOW())',
  'FROM freed f',
  'WHERE s.session_id = f.sid;'
].join('\n');

return [{ json: { sql, freeCount: free.length, poolSize: pool.length } }];

// Pull everything the coach report needs out of the end-of-call payload.
// Field paths are the ones observed on a real call (CLAUDE.md section 6), not assumed.
const raw = $input.first().json.raw || {};
const body = raw.body !== undefined ? raw.body : raw;
const msg = (body && body.message !== undefined) ? body.message : body;

const md =
  (msg.assistant && msg.assistant.metadata) ||
  (msg.call && msg.call.metadata) ||
  msg.metadata ||
  {};

const transcript = String(msg.transcript || (msg.artifact && msg.artifact.transcript) || '').trim();
const durationSeconds = Math.round(Number(msg.durationSeconds || (Number(msg.durationMs || 0) / 1000)) || 0);

const participantName = md.participantName || 'the participant';
const firstName = String(md.participantName || '').split(/\s+/)[0] || 'Participant';

// Structured turns for the email's transcript. Vapi's `messages[]` carries one
// entry per turn with role `bot` | `user` | `system`, which is far more reliable
// than re-parsing the flat transcript string. Fall back to parsing only if the
// array is absent.
let turns = [];
if (Array.isArray(msg.messages) && msg.messages.length) {
  for (const m of msg.messages) {
    const role = String(m.role || '').toLowerCase();
    if (role !== 'bot' && role !== 'user' && role !== 'assistant') continue;
    const text = String(m.message || m.content || '').trim();
    if (!text) continue;
    turns.push({ speaker: role === 'user' ? 'user' : 'ai', text });
  }
}
if (!turns.length && transcript) {
  // "AI: ...\nUser: ..." -- split on speaker labels at line starts.
  const parts = transcript.split(/\n(?=(?:AI|User|Assistant|Bot):\s)/i);
  for (const p of parts) {
    const mm = p.match(/^(AI|User|Assistant|Bot):\s*([\s\S]*)$/i);
    if (!mm) continue;
    const who = mm[1].toLowerCase();
    turns.push({ speaker: who === 'user' ? 'user' : 'ai', text: mm[2].trim() });
  }
}

// A call that barely happened should not produce a confident report.
const TOO_SHORT_SECONDS = 60;
const tooShort = durationSeconds < TOO_SHORT_SECONDS || transcript.length < 300;

const costTotal = (msg.costBreakdown && msg.costBreakdown.total) || msg.cost || null;

return [{
  json: {
    sessionId: md.sessionId || null,
    participantName,
    firstName,
    coachEmail: md.coachEmail || null,
    jobTitle: md.jobTitle || 'the role',
    jobLink: md.jobLink || null,
    nervousAbout: md.nervousAbout || null,
    focusArea: md.focusArea || null,
    assistantId: (msg.assistant && msg.assistant.id) || (msg.call && msg.call.assistantId) || null,
    callId: (msg.call && msg.call.id) || null,
    endedReason: msg.endedReason || null,
    durationSeconds,
    durationLabel: durationSeconds >= 60
      ? Math.floor(durationSeconds / 60) + 'm ' + (durationSeconds % 60) + 's'
      : durationSeconds + 's',
    transcript,
    transcriptChars: transcript.length,
    turns,
    turnCount: turns.length,
    vapiSummary: String(msg.summary || (msg.analysis && msg.analysis.summary) || '').trim() || null,
    recordingUrl: msg.recordingUrl || (msg.artifact && msg.artifact.recordingUrl) || null,
    costTotal,
    tooShort,
    // No coach selected means there is nowhere to send. Surfaced rather than thrown
    // so teardown still runs and the failure is visible in the execution.
    sendable: !!(md.coachEmail && transcript.length > 0)
  }
}];

